<?php if($user['role']!=='super_admin'){http_response_code(403);echo 'Super Admin required.';return;}
$target=(int)($_GET['employee_id']??0);$route=null;if($target){$q=$pdo->prepare("SELECT * FROM hr_records WHERE module='leave_route' AND employee_id=? AND status='Active' ORDER BY id DESC LIMIT 1");$q->execute([$target]);$route=$q->fetch(PDO::FETCH_ASSOC);}$values=$route?json_decode($route['data'],true):[];
$people=$pdo->query("SELECT u.id,u.name,u.role,e.employee_code FROM users u JOIN employees e ON e.user_id=u.id WHERE u.active=1 AND e.deleted_at IS NULL ORDER BY u.name")->fetchAll(PDO::FETCH_ASSOC);$approvers=[];foreach($pdo->query('SELECT id,name,role FROM users WHERE active=1 ORDER BY name') as $p)if(can($pdo,$p,'leave.approve'))$approvers[]=$p;
?><section class="card"><h2>Leave approval routing</h2><p>Configure who reviews new applications. Existing requests keep their snapshotted approvers. Without an explicit route, an eligible reporting manager is used; otherwise the Super Admin queue is used.</p><form method="get" class="form-grid"><input type="hidden" name="page" value="leave_routes"><label>Employee<select name="employee_id" required><option value="">Select employee</option><?php foreach($people as $p):?><option value="<?=(int)$p['id']?>" <?=$target===(int)$p['id']?'selected':''?>><?=h($p['name'].' · '.$p['employee_code'])?></option><?php endforeach;?></select></label><div><button class="button">Load route</button></div></form></section><?php if($target):?><section class="card"><form method="post" class="form-grid"><?php ftoken();?><input type="hidden" name="action" value="ess_route"><input type="hidden" name="employee_id" value="<?=$target?>"><input type="hidden" name="version" value="<?=(int)($route['version']??0)?>"><label>Approval mode<select name="mode"><option value="sequential" <?=($values['mode']??'')==='sequential'?'selected':''?>>Sequential — all stages must approve</option><option value="any" <?=($values['mode']??'')==='any'?'selected':''?>>Any one assigned approver</option></select></label><?php for($i=0;$i<3;$i++):?><label>Approver <?=$i+1?><select name="approvers[]" <?=$i===0?'required':''?>><option value="">None</option><?php foreach($approvers as $p)if((int)$p['id']!==$target):?><option value="<?=(int)$p['id']?>" <?=(int)($values['approvers'][$i]??0)===(int)$p['id']?'selected':''?>><?=h($p['name'])?></option><?php endif;?></select></label><?php endfor;?><p class="full">Grant Leave Approve permission in Roles & Permissions before selecting a Team Leader, Manager or HR approver. Job titles do not grant access.</p><button class="button primary">Save route for future requests</button></form></section><?php endif;?>
